-- ============================================================
-- Verify seed data
-- ============================================================
DO $$ DECLARE uid uuid; cnt int; BEGIN
  SELECT id INTO uid FROM auth.users LIMIT 1;
  SELECT COUNT(*) INTO cnt FROM workout_sessions WHERE user_id = uid;
  RAISE NOTICE 'Workout sessions: %', cnt;
  SELECT COUNT(*) INTO cnt FROM routines WHERE user_id = uid;
  RAISE NOTICE 'Routines: %', cnt;
  SELECT COUNT(*) INTO cnt FROM personal_records WHERE user_id = uid;
  RAISE NOTICE 'Personal records: %', cnt;
  SELECT COUNT(*) INTO cnt FROM exercise_progress WHERE user_id = uid;
  RAISE NOTICE 'Exercise progress entries: %', cnt;
  SELECT COUNT(*) INTO cnt FROM sets WHERE exercise_id IN (SELECT id FROM exercises WHERE session_id IN (SELECT id FROM workout_sessions WHERE user_id = uid));
  RAISE NOTICE 'Total sets: %', cnt;
  SELECT COUNT(*) INTO cnt FROM rep_summaries WHERE set_id IN (SELECT s.id FROM sets s JOIN exercises e ON s.exercise_id = e.id JOIN workout_sessions ws ON e.session_id = ws.id WHERE ws.user_id = uid);
  RAISE NOTICE 'Rep summaries: %', cnt;
END $$;